package com.tracker.controller;

import com.tracker.entity.*; import com.tracker.exception.ApiException; import com.tracker.repository.*; import com.tracker.service.AccessService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;

@RestController @RequestMapping("/api")
public class FeatureController {
  private final AccessService access; private final LearningGoalRepository goals; private final ProjectRepository projects; private final PortfolioRepository portfolios; private final WorkshopRepository workshops; private final WorkshopRegistrationRepository registrations; private final RecognitionRepository recognitions; private final NotificationRepository notifications; private final CareerRoleRepository roles; private final SkillRepository skills; private final CourseRepository courses; private final CertificationRepository certs;
  public FeatureController(AccessService a,LearningGoalRepository g,ProjectRepository p,PortfolioRepository o,WorkshopRepository w,WorkshopRegistrationRepository r,RecognitionRepository n,NotificationRepository q,CareerRoleRepository cr,SkillRepository s,CourseRepository c,CertificationRepository x){access=a;goals=g;projects=p;portfolios=o;workshops=w;registrations=r;recognitions=n;notifications=q;roles=cr;skills=s;courses=c;certs=x;}
  private User me(Authentication a){return access.current(a);} private void faculty(Authentication a){if(me(a).getRole()==Role.STUDENT)throw new ApiException("Faculty access required",HttpStatus.FORBIDDEN);} private <T> T own(Optional<T> value,String message){return value.orElseThrow(()->new ApiException(message,HttpStatus.NOT_FOUND));}

  @GetMapping("/goals") public List<LearningGoal> goals(Authentication a){return goals.findByUserIdOrderByTargetDateAsc(me(a).getId());}
  @PostMapping("/goals") public LearningGoal addGoal(@Valid @RequestBody LearningGoal x,Authentication a){x.setId(null);x.setUser(me(a));if(x.getProgress()==null)x.setProgress(0);if(x.getStatus()==null)x.setStatus("ACTIVE");return goals.save(x);}
  @PutMapping("/goals/{id}") public LearningGoal updateGoal(@PathVariable Long id,@Valid @RequestBody LearningGoal x,Authentication a){var old=own(goals.findByIdAndUserId(id,me(a).getId()),"Goal not found");old.setTitle(x.getTitle());old.setDescription(x.getDescription());old.setTargetSkill(x.getTargetSkill());old.setTargetCareer(x.getTargetCareer());old.setStartDate(x.getStartDate());old.setTargetDate(x.getTargetDate());old.setProgress(x.getProgress());old.setStatus(x.getProgress()!=null&&x.getProgress()>=100?"COMPLETED":x.getStatus());if("COMPLETED".equals(old.getStatus())&&old.getCompletedAt()==null)old.setCompletedAt(LocalDateTime.now());return goals.save(old);}
  @DeleteMapping("/goals/{id}") public void deleteGoal(@PathVariable Long id,Authentication a){goals.delete(own(goals.findByIdAndUserId(id,me(a).getId()),"Goal not found"));}

  @GetMapping("/projects") public List<Project> projects(Authentication a){return projects.findByUserIdOrderByCompletedDateDesc(me(a).getId());}
  @PostMapping("/projects") public Project addProject(@Valid @RequestBody Project x,Authentication a){x.setId(null);x.setUser(me(a));return projects.save(x);}
  @PutMapping("/projects/{id}") public Project updateProject(@PathVariable Long id,@Valid @RequestBody Project x,Authentication a){var old=own(projects.findByIdAndUserId(id,me(a).getId()),"Project not found");old.setTitle(x.getTitle());old.setDescription(x.getDescription());old.setTechnologies(x.getTechnologies());old.setProjectUrl(x.getProjectUrl());old.setRepositoryUrl(x.getRepositoryUrl());old.setCompletedDate(x.getCompletedDate());old.setPublished(x.isPublished());return projects.save(old);}
  @DeleteMapping("/projects/{id}") public void deleteProject(@PathVariable Long id,Authentication a){projects.delete(own(projects.findByIdAndUserId(id,me(a).getId()),"Project not found"));}

  @GetMapping("/portfolio") public Portfolio portfolio(Authentication a){return portfolios.findByUserId(me(a).getId()).orElseGet(()->{var p=new Portfolio();p.setUser(me(a));p.setPublicSlug(UUID.randomUUID().toString().replace("-",""));return portfolios.save(p);});}
  @PutMapping("/portfolio") public Portfolio updatePortfolio(@Valid @RequestBody Portfolio x,Authentication a){var p=portfolio(a);p.setPublicEnabled(x.isPublicEnabled());p.setShowEmail(x.isShowEmail());p.setShowSkills(x.isShowSkills());p.setShowProjects(x.isShowProjects());p.setShowCourses(x.isShowCourses());p.setShowCertificates(x.isShowCertificates());p.setIntroduction(x.getIntroduction());return portfolios.save(p);}
  @GetMapping("/public/portfolio/{slug}") public Map<String,Object> publicPortfolio(@PathVariable String slug){var p=own(portfolios.findByPublicSlugAndPublicEnabled(slug,true),"Portfolio not found");var u=p.getUser();Map<String,Object> out=new LinkedHashMap<>();out.put("name",u.getName());out.put("introduction",p.getIntroduction());if(p.isShowEmail())out.put("email",u.getEmail());if(p.isShowSkills())out.put("skills",skills.findByUserId(u.getId()));if(p.isShowProjects())out.put("projects",projects.findByUserIdOrderByCompletedDateDesc(u.getId()).stream().filter(Project::isPublished).toList());if(p.isShowCourses())out.put("courses",courses.findByUserId(u.getId()));if(p.isShowCertificates())out.put("certificates",certs.findByUserId(u.getId()).stream().filter(c->c.getStatus()==CertStatus.APPROVED).toList());return out;}

  @GetMapping("/workshops") public List<Workshop> publishedWorkshops(){return workshops.findByStatusOrderByStartAtAsc("PUBLISHED");}
  @GetMapping("/faculty/workshops") public List<Workshop> facultyWorkshops(Authentication a){faculty(a);return workshops.findByFacultyIdOrderByStartAtDesc(me(a).getId());}
  @PostMapping("/faculty/workshops") public Workshop addWorkshop(@Valid @RequestBody Workshop x,Authentication a){faculty(a);x.setId(null);x.setFaculty(me(a));return workshops.save(x);}
  @PutMapping("/faculty/workshops/{id}") public Workshop updateWorkshop(@PathVariable Long id,@Valid @RequestBody Workshop x,Authentication a){faculty(a);var old=own(workshops.findById(id),"Workshop not found");if(!old.getFaculty().getId().equals(me(a).getId())&&me(a).getRole()!=Role.ADMIN)throw new ApiException("Workshop access denied",HttpStatus.FORBIDDEN);old.setTitle(x.getTitle());old.setDescription(x.getDescription());old.setInstructor(x.getInstructor());old.setCategory(x.getCategory());old.setStartAt(x.getStartAt());old.setEndAt(x.getEndAt());old.setVenue(x.getVenue());old.setMeetingLink(x.getMeetingLink());old.setRegistrationDeadline(x.getRegistrationDeadline());old.setCapacity(x.getCapacity());old.setStatus(x.getStatus());return workshops.save(old);}
  @PostMapping("/workshops/{id}/register") public WorkshopRegistration registerWorkshop(@PathVariable Long id,Authentication a){var u=me(a);if(u.getRole()!=Role.STUDENT)throw new ApiException("Only students can register",HttpStatus.FORBIDDEN);var w=own(workshops.findById(id),"Workshop not found");if(!"PUBLISHED".equals(w.getStatus()))throw new ApiException("Workshop is not open for registration",HttpStatus.CONFLICT);if(w.getRegistrationDeadline()!=null&&w.getRegistrationDeadline().isBefore(LocalDateTime.now()))throw new ApiException("Registration is closed",HttpStatus.CONFLICT);if(registrations.existsByWorkshopIdAndStudentId(id,u.getId()))throw new ApiException("Already registered",HttpStatus.CONFLICT);if(w.getCapacity()!=null&&registrations.countByWorkshopId(id)>=w.getCapacity())throw new ApiException("Workshop is full",HttpStatus.CONFLICT);var r=new WorkshopRegistration();r.setWorkshop(w);r.setStudent(u);return registrations.save(r);}

  @GetMapping("/recognitions") public List<Recognition> recognitions(Authentication a){return recognitions.findByStudentIdOrderByAwardDateDesc(me(a).getId());}
  @PostMapping("/faculty/recognitions") public Recognition addRecognition(@Valid @RequestBody Recognition x,@RequestParam Long studentId,Authentication a){faculty(a);var student=access.byId(studentId);if(student.getRole()!=Role.STUDENT)throw new ApiException("Student not found",HttpStatus.NOT_FOUND);x.setId(null);x.setFaculty(me(a));x.setStudent(student);if(x.getAwardDate()==null)x.setAwardDate(LocalDate.now());return recognitions.save(x);}
  @GetMapping("/notifications") public Map<String,Object> notifications(Authentication a){var rows=notifications.findByUserIdOrderByCreatedAtDesc(me(a).getId());return Map.of("unread",notifications.countByUserIdAndReadFalse(me(a).getId()),"items",rows);}
  @PutMapping("/notifications/{id}/read") public Notification readNotification(@PathVariable Long id,Authentication a){var n=own(notifications.findById(id),"Notification not found");if(!n.getUser().getId().equals(me(a).getId()))throw new ApiException("Notification access denied",HttpStatus.FORBIDDEN);n.setRead(true);return notifications.save(n);}
  @PutMapping("/notifications/read-all") public void readAll(Authentication a){notifications.findByUserIdOrderByCreatedAtDesc(me(a).getId()).forEach(n->{n.setRead(true);notifications.save(n);});}

  @GetMapping("/career-roles") public List<CareerRole> careerRoles(){return roles.findAll();}
  @GetMapping("/career-roles/{id}/gap") public Map<String,Object> skillGap(@PathVariable Long id,Authentication a){var role=own(roles.findById(id),"Career role not found");var mine=skills.findByUserId(me(a).getId());Map<String,String> current=new HashMap<>();mine.forEach(s->current.put(s.getSkillName().toLowerCase(),s.getProficiency()));List<Map<String,Object>> required=role.getSkills().stream().map(r->{String p=current.get(r.getSkillName().toLowerCase());return Map.<String,Object>of("skill",r.getSkillName(),"target",r.getTargetProficiency(),"current",p==null?"Missing":p,"match",p!=null,"recommendation",r.getRecommendation()==null?"Practice and complete a relevant course":r.getRecommendation());}).toList();return Map.of("role",role.getName(),"required",required,"matched",required.stream().filter(x->Boolean.TRUE.equals(x.get("match"))).count(),"missing",required.stream().filter(x->!Boolean.TRUE.equals(x.get("match"))).count());}
  @GetMapping("/analytics/student") public Map<String,Object> analytics(Authentication a){var u=me(a);return Map.of("skillsByCategory",skills.findByUserId(u.getId()).stream().collect(java.util.stream.Collectors.groupingBy(Skill::getCategory,java.util.stream.Collectors.counting())),"coursesByStatus",courses.findByUserId(u.getId()).stream().collect(java.util.stream.Collectors.groupingBy(c->c.getStatus()==null?"COMPLETED":c.getStatus(),java.util.stream.Collectors.counting())),"certificatesByStatus",certs.findByUserId(u.getId()).stream().collect(java.util.stream.Collectors.groupingBy(c->c.getStatus().name(),java.util.stream.Collectors.counting())),"goalsActive",goals.countByUserIdAndStatus(u.getId(),"ACTIVE"),"goalsCompleted",goals.countByUserIdAndStatus(u.getId(),"COMPLETED"));}
}
